-- Intra-module foreign keys
ALTER TABLE org.institution ADD CONSTRAINT fk_institution_parent_institution_id FOREIGN KEY (parent_institution_id, tenant_id) REFERENCES org.institution (id, tenant_id) ON DELETE SET NULL (parent_institution_id);
CREATE INDEX ix_institution_parent_institution_id ON org.institution (parent_institution_id);
ALTER TABLE org.institution ADD CONSTRAINT fk_institution_institution_type_id FOREIGN KEY (institution_type_id, tenant_id) REFERENCES org.institution_type (id, tenant_id) ON DELETE SET NULL (institution_type_id);
CREATE INDEX ix_institution_institution_type_id ON org.institution (institution_type_id);
ALTER TABLE org.institution_attribute ADD CONSTRAINT fk_institution_attribute_institution_id FOREIGN KEY (institution_id, tenant_id) REFERENCES org.institution (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_institution_attribute_institution_id ON org.institution_attribute (institution_id);
ALTER TABLE org.institution_attribute ADD CONSTRAINT fk_institution_attribute_attribute_definition_id FOREIGN KEY (attribute_definition_id, tenant_id) REFERENCES org.attribute_definition (id, tenant_id) ON DELETE SET NULL (attribute_definition_id);
CREATE INDEX ix_institution_attribute_attribute_definition_id ON org.institution_attribute (attribute_definition_id);
ALTER TABLE org.department ADD CONSTRAINT fk_department_institution_id FOREIGN KEY (institution_id, tenant_id) REFERENCES org.institution (id, tenant_id) ON DELETE RESTRICT;
CREATE INDEX ix_department_institution_id ON org.department (institution_id);
ALTER TABLE org.department ADD CONSTRAINT fk_department_parent_department_id FOREIGN KEY (parent_department_id, tenant_id) REFERENCES org.department (id, tenant_id) ON DELETE SET NULL (parent_department_id);
CREATE INDEX ix_department_parent_department_id ON org.department (parent_department_id);
ALTER TABLE org.academic_year ADD CONSTRAINT fk_academic_year_institution_id FOREIGN KEY (institution_id, tenant_id) REFERENCES org.institution (id, tenant_id) ON DELETE RESTRICT;
CREATE INDEX ix_academic_year_institution_id ON org.academic_year (institution_id);
ALTER TABLE org.academic_term ADD CONSTRAINT fk_academic_term_academic_year_id FOREIGN KEY (academic_year_id, tenant_id) REFERENCES org.academic_year (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_academic_term_academic_year_id ON org.academic_term (academic_year_id);
ALTER TABLE org.academic_term ADD CONSTRAINT fk_academic_term_parent_term_id FOREIGN KEY (parent_term_id, tenant_id) REFERENCES org.academic_term (id, tenant_id) ON DELETE SET NULL (parent_term_id);
CREATE INDEX ix_academic_term_parent_term_id ON org.academic_term (parent_term_id);
ALTER TABLE org.institution_type_attribute ADD CONSTRAINT fk_institution_type_attribute_institution_type_id FOREIGN KEY (institution_type_id, tenant_id) REFERENCES org.institution_type (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_institution_type_attribute_institution_type_id ON org.institution_type_attribute (institution_type_id);
ALTER TABLE org.institution_type_attribute ADD CONSTRAINT fk_institution_type_attribute_attribute_definition_id FOREIGN KEY (attribute_definition_id, tenant_id) REFERENCES org.attribute_definition (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_institution_type_attribute_attribute_definition_id ON org.institution_type_attribute (attribute_definition_id);
ALTER TABLE org.holiday ADD CONSTRAINT fk_holiday_institution_id FOREIGN KEY (institution_id, tenant_id) REFERENCES org.institution (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_holiday_institution_id ON org.holiday (institution_id);

-- === P1-16: uniform reference-data shape ===

CREATE UNIQUE INDEX uq_institution_type_scope_code ON org.institution_type (tenant_id, code) WHERE deleted_at IS NULL;

-- === P1-09: nested terms ===

CREATE UNIQUE INDEX uq_academic_term_name ON org.academic_term (academic_year_id, parent_term_id, name) NULLS NOT DISTINCT WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uq_academic_term_start ON org.academic_term (academic_year_id, parent_term_id, start_date) NULLS NOT DISTINCT WHERE deleted_at IS NULL;

-- === P1-13: transactional outbox / inbox ===

CREATE TABLE org.outbox_event (
    id bigint GENERATED ALWAYS AS IDENTITY,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    aggregate_type varchar(80) NOT NULL,
    aggregate_id uuid NOT NULL,
    payload text NOT NULL,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    CONSTRAINT pk_org_outbox_event PRIMARY KEY (id)
);
COMMENT ON TABLE org.outbox_event IS 'Transactional outbox of the org module: events written in the same transaction as the change, published to the bus by a relay, then pruned. Ordered by the identity column.';
COMMENT ON COLUMN org.outbox_event.id IS 'Monotonic sequence; publish order.';
COMMENT ON COLUMN org.outbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN org.outbox_event.event_type IS 'Event name (module.entity.verb).';
COMMENT ON COLUMN org.outbox_event.aggregate_type IS 'Entity kind the event is about.';
COMMENT ON COLUMN org.outbox_event.aggregate_id IS 'Entity id the event is about.';
COMMENT ON COLUMN org.outbox_event.payload IS 'Serialised event (opaque message envelope).';
COMMENT ON COLUMN org.outbox_event.occurred_at IS 'When the change committed.';
COMMENT ON COLUMN org.outbox_event.published_at IS 'When the relay published it (NULL = pending).';
CREATE INDEX ix_org_outbox_event_pending ON org.outbox_event (id) WHERE published_at IS NULL;
CREATE TABLE org.inbox_event (
    event_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    received_at timestamptz NOT NULL DEFAULT now(),
    processed_at timestamptz,
    processing_error text,
    CONSTRAINT pk_org_inbox_event PRIMARY KEY (event_id)
);
COMMENT ON TABLE org.inbox_event IS 'Inbox of the org module: ids of consumed events, kept so redeliveries are processed exactly once.';
COMMENT ON COLUMN org.inbox_event.event_id IS 'Global id of the consumed event.';
COMMENT ON COLUMN org.inbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN org.inbox_event.event_type IS 'Event name.';
COMMENT ON COLUMN org.inbox_event.received_at IS 'First delivery time.';
COMMENT ON COLUMN org.inbox_event.processed_at IS 'When handling committed (NULL = in flight).';
COMMENT ON COLUMN org.inbox_event.processing_error IS 'Last handling error, if any.';

-- === P1-15: business uniqueness ignores soft-deleted rows ===

CREATE UNIQUE INDEX uq_academic_year_1 ON org.academic_year (institution_id, name) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uq_attribute_definition_1 ON org.attribute_definition (tenant_id, name) WHERE deleted_at IS NULL;
